# Define a function to split the 'var2' column
def split_row(group):
    splits = group['var2'].str.split('-')
    rows = []
    for _, row in group.iterrows():
        for val in splits.loc[_]:
            if pd.notna(val):
                rows.append({'var1': row['var1'], 'var2': val})
    return pd.DataFrame(rows)

